  auto line=quote_windows_argument(exe.wstring())+L" "+args;auto desktop=current_desktop_path();STARTUPINFOEXW si{};si.StartupInfo.cb=sizeof(STARTUPINFOW);si.StartupInfo.lpDesktop=desktop.data();Handle output,input;std::vector<unsigned char> attributes;DWORD flags=CREATE_NO_WINDOW;
  if(capture){diagnostic=root/(inherited?"continuation-wait.log":"protected-bootstrap.log");SECURITY_ATTRIBUTES sa{sizeof(sa),nullptr,TRUE};output.reset(CreateFileW(diagnostic.c_str(),GENERIC_WRITE,FILE_SHARE_READ,&sa,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr));input.reset(CreateFileW(L"NUL",GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE,&sa,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr));check(output&&input,"Open OWNED synthetic bootstrap diagnostics");si.StartupInfo.cb=sizeof(si);si.StartupInfo.dwFlags=STARTF_USESTDHANDLES;si.StartupInfo.hStdInput=input.get();si.StartupInfo.hStdOutput=si.StartupInfo.hStdError=output.get();SIZE_T bytes{};InitializeProcThreadAttributeList(nullptr,1,0,&bytes);attributes.resize(bytes);si.lpAttributeList=reinterpret_cast<LPPROC_THREAD_ATTRIBUTE_LIST>(attributes.data());require(InitializeProcThreadAttributeList(si.lpAttributeList,1,0,&bytes),"Initialize fixture safe handles");HANDLE handles[]={input.get(),output.get(),inherited};if(!UpdateProcThreadAttribute(si.lpAttributeList,0,PROC_THREAD_ATTRIBUTE_HANDLE_LIST,handles,sizeof(HANDLE)*(inherited?3:2),nullptr,nullptr)){DeleteProcThreadAttributeList(si.lpAttributeList);fail("Restrict fixture diagnostic handles");}flags|=EXTENDED_STARTUPINFO_PRESENT;}
  PROCESS_INFORMATION pi{};auto created=CreateProcessW(exe.c_str(),line.data(),nullptr,nullptr,capture,flags,nullptr,nullptr,&si.StartupInfo,&pi);auto error=GetLastError();if(si.lpAttributeList)DeleteProcThreadAttributeList(si.lpAttributeList);if(!created)fail("Launch actual headless image",error);process.reset(pi.hProcess);CloseHandle(pi.hThread);
